import pandas as pd
from flask import Flask, request, jsonify

app = Flask(__name__)
data = pd.DataFrame({'a': [1, 2]})
state = {'custom': False}

@app.post('/settings')
def settings():
    state['custom'] = request.get_json().get('enable_custom_filters', state['custom'])
    return jsonify(ok=True)

@app.get('/query')
def query():
    q = request.args.get('query')
    if q and not state['custom']:
        return jsonify(error='disabled')
    rows = data.query(q).to_dict('records')
    return jsonify(rows)

