from urllib.parse import urljoin, urlparse
from flask import Flask, redirect, request

app = Flask(__name__)

def is_safe_url(location):
    ref = urlparse(request.host_url)
    test = urlparse(urljoin(request.host_url, location))
    return test.scheme in ('http', 'https') and ref.netloc == test.netloc

@app.get('/login')
def login():
    for location in request.values.get('next'), request.referrer:
        if location and is_safe_url(location):
            return redirect(location)
    return 'login form'

import posixpath
from urllib.parse import unquote
from flask import Flask, request, redirect

app = Flask(__name__)

def sanitize(path):
    decoded = path
    for _ in range(8):
        once = unquote(decoded)
        if once == decoded:
            break
        decoded = once
    cleaned = posixpath.normpath(decoded).lstrip('/')
    if cleaned.startswith('..') or cleaned == '.':
        return None
    return cleaned

@app.get('/proxy/<path:path>')
def proxy(path):
    safe = sanitize(path)
    if safe is None:
        return 'bad', 400
    return redirect('/static/' + safe)

