app = Flask(__name__)

def get_safe_url(url):
    if not url:
        return '/'
    parsed = urlparse(url)
    if parsed.scheme in ['http', 'https', ''] and parsed.netloc in [request.host, '']:
        return url
    return '/'

@app.post('/run')
def run():
    origin = get_safe_url(request.form.get('origin'))
    return redirect(origin)

from urllib.parse import urlparse
import ipaddress, socket, requests

def is_global_host(host):
    try:
        return ipaddress.ip_address(socket.gethostbyname(host)).is_global
    except (OSError, ValueError):
        return False

def parse_urls(url=None):
    if url:
        parsed = urlparse(url)
        if parsed.scheme in ('http', 'https') and parsed.hostname and is_global_host(parsed.hostname):
            return requests.get(url).text
    return ''

from flask import Flask, redirect, render_template_string, request
from urllib.parse import urlparse

app = Flask(__name__)
TPL = '<script>var REDIRECT_URL = "{{ redirect_url|e }}";</script>'

@app.get('/login')
def login():
    redirect_url = request.args.get('redirect', '/')
    parsed = urlparse(redirect_url)
    if parsed.scheme != '' or parsed.netloc != '':
        redirect_url = '/'
    return render_template_string(TPL, redirect_url=redirect_url)

